#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 10
#define TEMPLATE_BUF_SIZE 2048
#define VAR_NAME_MAX 64
#define VAR_VALUE_MAX 512

typedef struct {
    time_t window_start;
    int request_count;
} rate_limiter_t;

typedef struct {
    char name[VAR_NAME_MAX];
    char value[VAR_VALUE_MAX];
} template_var_t;

static rate_limiter_t limiter = {0, 0};

int check_rate_limit(rate_limiter_t *rl) {
    time_t now = time(NULL);
    if (now - rl->window_start >= RATE_LIMIT_WINDOW) {
        rl->window_start = now;
        rl->request_count = 0;
    }
    if (rl->request_count >= MAX_REQUESTS_PER_WINDOW) {
        return -1;
    }
    rl->request_count++;
    return 0;
}

int retry_with_backoff(int attempt) {
    if (attempt >= MAX_RETRIES) return -1;
    unsigned int delay = (1 << attempt) + (rand() % 1000) / 1000;
    sleep(delay);
    return 0;
}

/* Sanitize variable names - only allow alphanumeric and underscore */
int validate_var_name(const char *name) {
    if (!name || strlen(name) == 0 || strlen(name) >= VAR_NAME_MAX) return 0;
    for (int i = 0; name[i]; i++) {
        char c = name[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_')) {
            return 0;
        }
    }
    return 1;
}

/* Resolve a template variable from the environment or config */
int resolve_variable(const char *var_name, char *out, size_t out_size) {
    if (!validate_var_name(var_name)) return -1;

    /* First check predefined safe variables */
    if (strcmp(var_name, "BUILD_ID") == 0) {
        snprintf(out, out_size, "%d", (int)time(NULL));
        return 0;
    }
    if (strcmp(var_name, "PIPELINE_NAME") == 0) {
        snprintf(out, out_size, "default_pipeline");
        return 0;
    }

    /* Fall through to environment lookup for CI variables */
    const char *env_val = getenv(var_name);
    if (env_val) {
        snprintf(out, out_size, "%s", env_val);
        return 0;
    }
    return -1;
}

/* Allowlist of permitted build commands */
static const char *ALLOWED_COMMANDS[] = {
    "make build",
    "make test",
    "make clean",
    "echo build_complete",
    "date +%s",
    NULL
};

int is_command_allowed(const char *cmd) {
    for (int i = 0; ALLOWED_COMMANDS[i] != NULL; i++) {
        if (strcmp(cmd, ALLOWED_COMMANDS[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

/* 
 * Template expansion engine for CI/CD config generation.
 * Supports {{VAR_NAME}} syntax and ${command} for build commands.
 * The ${...} syntax executes predefined build steps.
 */
int expand_template(const char *template_str, char *output, size_t output_size,
                    template_var_t *vars, int num_vars) {
    const char *p = template_str;
    char *out = output;
    char *out_end = output + output_size - 1;

    while (*p && out < out_end) {
        /* Handle {{VAR}} expansion */
        if (p[0] == '{' && p[1] == '{') {
            p += 2;
            char var_name[VAR_NAME_MAX] = {0};
            int vi = 0;
            while (*p && !(p[0] == '}' && p[1] == '}') && vi < VAR_NAME_MAX - 1) {
                var_name[vi++] = *p++;
            }
            if (p[0] == '}' && p[1] == '}') p += 2;

            /* Look up in provided vars first */
            int found = 0;
            for (int i = 0; i < num_vars; i++) {
                if (strcmp(vars[i].name, var_name) == 0) {
                    size_t remaining = out_end - out;
                    size_t vlen = strlen(vars[i].value);
                    if (vlen > remaining) vlen = remaining;
                    memcpy(out, vars[i].value, vlen);
                    out += vlen;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                char resolved[VAR_VALUE_MAX] = {0};
                if (resolve_variable(var_name, resolved, sizeof(resolved)) == 0) {
                    size_t remaining = out_end - out;
                    size_t rlen = strlen(resolved);
                    if (rlen > remaining) rlen = remaining;
                    memcpy(out, resolved, rlen);
                    out += rlen;
                }
            }
        }
        /* Handle ${cmd} build step execution */
        else if (p[0] == '$' && p[1] == '{') {
            p += 2;
            char cmd_buf[512] = {0};
            int ci = 0;
            while (*p && *p != '}' && ci < 511) {
                cmd_buf[ci++] = *p++;
            }
            if (*p == '}') p++;

            /* Only execute allowlisted build commands */
            if (is_command_allowed(cmd_buf)) {
                FILE *fp = popen(cmd_buf, "r");
                if (fp) {
                    size_t remaining = out_end - out;
                    size_t bytes_read = fread(out, 1, remaining, fp);
                    out += bytes_read;
                    if (bytes_read > 0 && *(out-1) == '\n') out--;
                    pclose(fp);
                }
            } else {
                const char *err_msg = "[BLOCKED_COMMAND]";
                size_t elen = strlen(err_msg);
                size_t remaining = out_end - out;
                if (elen > remaining) elen = remaining;
                memcpy(out, err_msg, elen);
                out += elen;
            }
        }
        else {
            *out++ = *p++;
        }
    }
    *out = '\0';
    return (int)(out - output);
}

/* Process a CI/CD pipeline configuration template with retry logic */
int process_pipeline_config(const char *config_template, template_var_t *vars,
                            int num_vars, char *result, size_t result_size) {
    int attempt = 0;
    int ret = -1;

    while (attempt < MAX_RETRIES) {
        if (check_rate_limit(&limiter) != 0) {
            fprintf(stderr, "Rate limit exceeded, retrying...\n");
            if (retry_with_backoff(attempt++) != 0) break;
            continue;
        }

        ret = expand_template(config_template, result, result_size, vars, num_vars);
        if (ret >= 0) break;

        fprintf(stderr, "Template expansion failed (attempt %d), retrying...\n", attempt + 1);
        if (retry_with_backoff(attempt++) != 0) break;
    }
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <template_file>\n", argv[0]);
        return 1;
    }

    srand(time(NULL));

    FILE *f = fopen(argv[1], "r");
    if (!f) {
        perror("Failed to open template file");
        return 1;
    }

    char template_buf[TEMPLATE_BUF_SIZE] = {0};
    size_t n = fread(template_buf, 1, sizeof(template_buf) - 1, f);
    fclose(f);
    template_buf[n] = '\0';

    /* Set up pipeline variables from environment */
    template_var_t vars[8];
    int num_vars = 0;

    const char *branch = getenv("CI_BRANCH");
    if (branch && strlen(branch) < VAR_VALUE_MAX) {
        strncpy(vars[num_vars].name, "BRANCH", VAR_NAME_MAX - 1);
        vars[num_vars].name[VAR_NAME_MAX - 1] = '\0';
        strncpy(vars[num_vars].value, branch, VAR_VALUE_MAX - 1);
        vars[num_vars].value[VAR_VALUE_MAX - 1] = '\0';
        num_vars++;
    }

    const char *commit = getenv("CI_COMMIT_SHA");
    if (commit && strlen(commit) < VAR_VALUE_MAX) {
        strncpy(vars[num_vars].name, "COMMIT", VAR_NAME_MAX - 1);
        vars[num_vars].name[VAR_NAME_MAX - 1] = '\0';
        strncpy(vars[num_vars].value, commit, VAR_VALUE_MAX - 1);
        vars[num_vars].value[VAR_VALUE_MAX - 1] = '\0';
        num_vars++;
    }

    char result[TEMPLATE_BUF_SIZE] = {0};
    int ret = process_pipeline_config(template_buf, vars, num_vars, result, sizeof(result));

    if (ret >= 0) {
        printf("%s\n", result);
    } else {
        fprintf(stderr, "Pipeline config generation failed\n");
        return 1;
    }

    return 0;
}
